-- clean re-run: remove existing specialization + level rows of the first 5 subjects
DELETE FROM subject_sections WHERE specialization_id IS NOT NULL AND study_level_id IS NOT NULL
  AND subject_id IN (SELECT id FROM subjects WHERE display_order BETWEEN 11 AND 15);

CREATE TEMP TABLE combo AS
SELECT s.id subject_id, s.name subject_name, sp.id spec_id, sp.name spec_name, i.focus, i.roles,
       l.id level_id, l.name level_name, l.slug level_slug, l.description level_desc
FROM subjects s
JOIN specializations sp ON sp.subject_id=s.id
JOIN sp_info i ON i.ord=s.display_order AND i.name=sp.name
JOIN subject_study_levels ssl ON ssl.subject_id=s.id
JOIN study_levels l ON l.id=ssl.study_level_id
WHERE s.display_order BETWEEN 11 AND 15 AND s.status='published' AND sp.status='published';

-- About
INSERT INTO subject_sections(id,subject_id,specialization_id,study_level_id,section,title,body,status,display_order)
SELECT gen_random_uuid(),subject_id,spec_id,level_id,'about',
  'About '||level_name||' in '||spec_name,
  '<p>A '||level_name||' in '||spec_name||' focuses on '||focus||'. '||level_desc||'</p>'
  ||'<p>'||CASE level_slug
     WHEN 'foundation' THEN 'It prepares you for a bachelor''s degree in '||spec_name||' or a related field by building subject knowledge and English skills.'
     WHEN 'pathway' THEN 'It leads into the first or second year of a '||spec_name||' degree at a partner university.'
     WHEN 'diploma' THEN 'It gives practical, job-focused training in '||spec_name||' and can count toward a bachelor''s degree.'
     WHEN 'bachelors' THEN 'You study the core theory and practice of '||spec_name||', usually with projects, and often a placement or dissertation.'
     WHEN 'masters' THEN 'You deepen specialist knowledge of '||spec_name||' through advanced modules and a project or dissertation.'
     WHEN 'mba' THEN 'You apply '||spec_name||' to leadership and management decisions alongside experienced classmates.'
     ELSE 'You carry out original research in '||spec_name||' under a supervisor and write a thesis.' END||'</p>',
  'published',1 FROM combo;

-- Why
INSERT INTO subject_sections(id,subject_id,specialization_id,study_level_id,section,title,body,status,display_order)
SELECT gen_random_uuid(),subject_id,spec_id,level_id,'why',
  'Why choose a '||level_name||' in '||spec_name||'?',
  CASE WHEN level_slug IN ('foundation','pathway','diploma')
   THEN '<p>A '||level_name||' is a step toward a degree in '||spec_name||'. Graduates typically progress to a bachelor''s and then to roles such as '||roles||'.</p>'
   ELSE '<p>A '||level_name||' in '||spec_name||' builds the skills employers look for. Typical roles include '||roles||'.</p>' END
  ||'<p>Entry requirements, costs, intakes and work rights differ by country and university, so compare destinations before you apply.</p>',
  'published',1 FROM combo;

-- Shared blocks copied from the subject page (industries, employers, destinations)
INSERT INTO subject_sections(id,subject_id,specialization_id,study_level_id,section,title,subtitle,body,url,is_sponsored,status,display_order)
SELECT gen_random_uuid(),c.subject_id,c.spec_id,c.level_id,x.section,x.title,x.subtitle,x.body,x.url,x.is_sponsored,'published',x.display_order
FROM combo c
JOIN subject_sections x ON x.subject_id=c.subject_id AND x.study_level_id IS NULL AND x.specialization_id IS NULL
 AND x.status='published' AND x.section IN ('industry','company','destination','course','university');
COMMIT;
